const testCases = [
  {
    test_id: "T1",
    test_type: "Detailed Transcript",
    input: "The user should be able to filter reports by date range, category, and status. Results must load in under 2 seconds. PM: Sarah. Deadline: Q3.",
    expected: "Extract date/category/status filters, load time under 2 seconds, Sarah as PM, and Q3 deadline. Do not invent requirements."
  },
  {
    test_id: "T2",
    test_type: "Vague Brief",
    input: "We need better reporting. Something like what Competitor X has.",
    expected: "Flag ambiguity and missing metrics, formats, and target users. Do not invent requirements."
  },
  {
    test_id: "T3",
    test_type: "Contradictory Requirements",
    input: "The dashboard should auto-refresh every 5 seconds. Later: Performance is critical, minimize API calls.",
    expected: "Identify the tension between frequent refresh and minimizing API calls. Flag for stakeholder clarification."
  }
];

return testCases.map(tc => ({
  json: tc
}));

const testCases = $input.all();

return testCases.map(item => {
  const tc = item.json;

  const document = {
    source_id: "DOC-001",
    file_name: `${tc.test_id}.txt`,
    source_type: "Meeting Transcript",
    content: tc.input
  };

  const transcript =
    `=== SOURCE ${document.source_id}: ${document.file_name} ===\n` +
    `Source Type: ${document.source_type}\n\n` +
    document.content;

  return {
    json: {
      test_id: tc.test_id,
      test_type: tc.test_type,
      expected: tc.expected,
      document_count: 1,
      documents: [document],
      transcript: transcript
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  const id = data.test_id;
  const result = data.output || {};

  const fr = result.functional_requirements || [];
  const nfr = result.non_functional_requirements || [];
  const requirements = [...fr, ...nfr];

  const requirementText = requirements
    .map(r => r.requirement || "")
    .join(" ")
    .toLowerCase();

  let checks = {};

  // T1 — Detailed Transcript
  if (id === "T1") {
    const stakeholders = result.stakeholders || [];
    const deadlines = result.deadlines || [];

    checks = {
      date_filter: requirementText.includes("date"),
      category_filter: requirementText.includes("category"),
      status_filter: requirementText.includes("status"),
      performance: /2\s*seconds?/.test(requirementText),

      stakeholder: stakeholders.some(s =>
        (s.name || "").toLowerCase() === "sarah"
      ),

      deadline: deadlines.some(d =>
        (d.target || "").toLowerCase().includes("q3")
      ),

      grounding: data.validation?.passed === true
    };
  }

  // T2 — Vague Brief
  else if (id === "T2") {
    const ambiguities = result.ambiguous_or_tbd_items || [];
    const questions = result.open_questions || [];

    const clarificationText = [...ambiguities, ...questions]
      .join(" ")
      .toLowerCase();

    checks = {
      ambiguity_flagged:
        ambiguities.length > 0 || questions.length > 0,

      missing_metrics_identified:
        /metric|measur|success criteria|acceptance criteria/
          .test(clarificationText),

      missing_scope_identified:
        /feature|report|scope|format/
          .test(clarificationText),

      no_confirmed_requirements:
        requirements.every(r => r.status !== "confirmed"),

      grounding: data.validation?.passed === true
    };
  }

  // T3 — Contradictory Requirements
  else if (id === "T3") {
    const contradictions = result.contradictions || [];
    const questions = result.open_questions || [];
    const ambiguities = result.ambiguous_or_tbd_items || [];

    const clarificationText = [
      ...questions,
      ...ambiguities,
      ...contradictions.map(c =>
        c.clarification_question || ""
      )
    ].join(" ").toLowerCase();

    checks = {
      refresh_interval_preserved:
        /5\s*seconds?/.test(requirementText),

      api_constraint_preserved:
        /api calls?/.test(requirementText),

      tension_identified:
        contradictions.length > 0 ||
        /reconcil|trade.off|conflict|priority/
          .test(clarificationText),

      clarification_requested:
        questions.length > 0 &&
        /refresh|api calls?|priority/
          .test(clarificationText),

      no_silent_resolution:
        requirements.every(r => r.status !== "confirmed"),

      grounding: data.validation?.passed === true
    };
  }

  // Other test cases — Not evaluated yet
  else {
    return {
      json: {
        test_id: id,
        result: "NOT_EVALUATED",
        reason: "Evaluation rules not added yet"
      }
    };
  }

  // Common reporting logic for T1, T2 and T3
  const failedChecks = Object.entries(checks)
    .filter(([, passed]) => !passed)
    .map(([key]) => key);

  const validationErrors = data.validation?.errors || [];

  const passed =
    failedChecks.length === 0 &&
    validationErrors.length === 0;

  return {
    json: {
      test_id: id,
      result: passed ? "PASS" : "FAIL",
      checks,
      failed_checks: failedChecks,
      validation_errors: validationErrors,
      failure_reason: passed
        ? "All automated checks passed"
        : [
            ...failedChecks.map(
              check => `Evaluation check failed: ${check}`
            ),
            ...validationErrors.map(
              error => `Validation error: ${error}`
            )
          ].join("; "),
      total_requirements:
        data.validation?.total_requirements ?? 0,
      evidence_verified:
        data.validation?.evidence_verified ?? 0
    }
  };
});
